# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.models import Span
from hourglass.gaps import find_gaps


def spans_from(*texts):
    return [parse_span(text) for text in texts]


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        worked = spans_from("09:00-12:00", "13:00-17:00")
        self.assertEqual(
            find_gaps(worked, parse_span("09:00-17:00")),
            ["gap 12:00-13:00 (60 min)"],
        )

    def test_gaps_at_both_ends(self):
        worked = spans_from("10:00-11:00")
        self.assertEqual(
            find_gaps(worked, parse_span("09:00-12:30")),
            ["gap 09:00-10:00 (60 min)", "gap 11:00-12:30 (90 min)"],
        )

    def test_full_coverage_has_no_gaps(self):
        worked = spans_from("09:00-13:00", "12:00-17:00")
        self.assertEqual(find_gaps(worked, parse_span("09:00-17:00")), [])

    def test_touching_spans_leave_no_gap(self):
        worked = spans_from("09:00-13:00", "13:00-17:00")
        self.assertEqual(find_gaps(worked, parse_span("09:00-17:00")), [])

    def test_nobody_working_is_one_big_gap(self):
        self.assertEqual(
            find_gaps([], parse_span("09:00-17:00")),
            ["gap 09:00-17:00 (480 min)"],
        )

    def test_unordered_input(self):
        worked = spans_from("14:00-17:00", "09:00-11:00")
        self.assertEqual(
            find_gaps(worked, parse_span("09:00-17:00")),
            ["gap 11:00-14:00 (180 min)"],
        )

    def test_span_outside_opening_hours_raises(self):
        opening = parse_span("09:00-17:00")
        for text in ("08:00-10:00", "16:00-18:00", "06:00-07:00"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    find_gaps(spans_from(text), opening)

    def test_span_matching_opening_hours_is_fine(self):
        self.assertEqual(find_gaps([Span(540, 1020)], Span(540, 1020)), [])


if __name__ == "__main__":
    unittest.main()
